fn main() -> Int {
  let words: Vec[Str] = Vec[Str].new();
  words.push("apple");
  words.push("banana");
  words.push("apple");
  words.push("cherry");
  words.push("banana");
  words.push("apple");

  let counts: Map[Str,Int] = Map[Str,Int].new();
  for __i in range(0, words.len()) {
    let word = words[__i];
    match counts.get(word) {
      Some(n) => counts.insert(word, n + 1);
      None => counts.insert(word, 1);
    }
  }

  match counts.get("apple") {
    Some(n) => io.println("apple: " + to_string(n));
    None => {}
  }
  match counts.get("banana") {
    Some(n) => io.println("banana: " + to_string(n));
    None => {}
  }
  match counts.get("cherry") {
    Some(n) => io.println("cherry: " + to_string(n));
    None => {}
  }
  return 0;
}
